#include <stdio.h>

double circle_area(double radius)
{
    const double pi = 3.14159265358979;
    return pi * radius * radius;
}

void print_line(int width)
{
    for (int i = 0; i < width; i++) {
        printf("-");
    }
    printf("\n");
}

int main(void)
{
    print_line(20);
    printf("radius 1.0: %.2f\n", circle_area(1.0));
    printf("radius 2.5: %.2f\n", circle_area(2.5));
    print_line(20);
    return 0;
}

#include <stdio.h>

int max_of(int a, int b);                 /* prototypes */
int clamp(int value, int low, int high);

int main(void)
{
    printf("%d\n", max_of(3, 9));
    printf("%d\n", clamp(15, 0, 10));
    printf("%d\n", clamp(-4, 0, 10));
    return 0;
}

int max_of(int a, int b)
{
    return a > b ? a : b;
}

int clamp(int value, int low, int high)
{
    if (value < low) return low;
    if (value > high) return high;
    return value;
}

