#include <stdio.h>

unsigned long long factorial(unsigned int n)
{
    if (n <= 1) {
        return 1;                 /* base case stops the recursion */
    }
    return n * factorial(n - 1);  /* recursive case */
}

int main(void)
{
    for (unsigned int i = 0; i <= 5; i++) {
        printf("%u! = %llu\n", i, factorial(i));
    }
    printf("20! = %llu\n", factorial(20));
    return 0;
}

#include <stdio.h>

int next_id(void)
{
    static int last = 0;   /* initialised once, kept between calls */
    last++;
    return last;
}

int main(void)
{
    printf("%d\n", next_id());
    printf("%d\n", next_id());
    printf("%d\n", next_id());
    return 0;
}

